"use strict";
let age = 25;
console.log(age);
// Integer
let marks = 30;
console.log(marks);
// Float
let percentage = 90.2;
console.log(percentage);
// Negative Number
let temp = -80.02;
console.log(temp);
// Special values in number
// NaN => due to invalid calculations
let result = 0 / 0;
console.log(result);
// Infinity
let data = 10 / 0;
console.log(data);
// Addition
let a = 20;
let b = 10;
console.log(a + b);
console.log(a - b);
console.log(a * b);
console.log(a / b);
console.log(a % b);
// function 
function add(a, b) {
    return a + b;
}
console.log(add(10, 20));
